        lc=g[0][v[0]]; L=v[0]; out=[row[:] for row in g]
        def claims(r,c): return [(r,c,g[r][c])] if g[r][c] not in (bgc,lc) else []
        marks=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c] not in (bgc,lc)]
        for (mr,mc,mcol) in marks:
            # bracketing lines: none (single vertical line); pair with it if mc!=L else skip
            if mc==L: continue
            brs={mr-1,mr+1}; bcs={L-1,L+1}
            for r in brs:
                if 0<=r<H:
                    for c in bcs:
                        if 0<=c<W: out[r][c]=lc
            for c in bcs:
                if 0<=c<W:
                    for r in brs:
                        if 0<=r<H: out[r][c]=lc
            # line cells within band -> marker color
            if mr-1>=0 and L-1>=0: out[mr-1][L]=mcol
            if mr+1<H and L+1<W: out[mr+1][L]=mcol
            # run toward line
            step=-1 if mc<L else 1
            if step==-1: rng=range(mc+1,L)
            else: rng=range(L+1,mc)
            for c in rng:
                if out[mr][c]==bgc: out[mr][c]=mcol
        return out
    else:  # horizontal lines
        lc=g[h[0]][0]; Ll=h[0]; out=[row[:] for row in g]
        marks=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c] not in (bgc,lc)]
        lines=set(h)
        # pair each marker with bracketing lines
        for (mr,mc,mcol) in marks:
            bs=[L for L in lines if L<mr<Ll or Ll<L<mr]  # bracketing: line < marker < some other line
            for L in bs:
                bcs={mc-1,mc+1}; brs={L-1,L+1}
                for c in bcs:
                    if 0<=c<W:
                        for r in brs:
                            if 0<=r<H: out[r][c]=lc
                out[L][mc]=mcol
                # run toward line along column
                step=-1 if L<mr else 1
                if step==-1: rng=range(L+2,mr)   # between line+1edge... band rows L-1,L+1; run rows strictly between band near edge and marker
                else: rng=range(mr+1,L-1)
                for r in rng:
                    if out[r][mc]==bgc: out[r][mc]=mcol
        return out
